package io.github.theamethyx.femboyclient.client.gui;

/**
 * Cells of {@code textures/gui/icons.png}, generated by {@code tools/make_icons.py} in this order: vector glyphs rendered
 * at 32 pixels per cell and filtered smoothly when drawn smaller, tinted at draw time.
 */
public enum Icon {
	DASHBOARD, VISUAL, ANALYSIS, SCENARIOS, RESULTS, PERFORMANCE, SETTINGS, HUD,
	UTILITY, SEARCH, RESET, KEY, CHECK, WARNING, CHEVRON_DOWN, CLOSE,
	PLUS, TRASH, INFO, LOCK, STAR, FOLDER, PLAY, STOP,
	HOME, PLAYER, STORAGE, NAVIGATE, PAUSE, COMBAT, CODE, ARROW,
	SUN, TARGET, BELL, GLOBE, BOLT, MOVEMENT, LAYERS, SLIDERS,
	HEART, SPARKLE, CHEVRON_RIGHT;

	public static final int CELL = 32;
	public static final int ATLAS_WIDTH = 256;
	public static final int ATLAS_HEIGHT = 192;

	public int u() {
		return (ordinal() % 8) * CELL;
	}

	public int v() {
		return (ordinal() / 8) * CELL;
	}

	/** Maps a module category's icon name to its glyph. */
	public static Icon byName(String name) {
		return switch (name) {
			case "hud" -> HUD;
			case "visual" -> VISUAL;
			case "analysis" -> ANALYSIS;
			case "utility" -> UTILITY;
			case "player" -> PLAYER;
			case "combat" -> COMBAT;
			case "developer" -> CODE;
			case "movement" -> MOVEMENT;
			case "automation" -> BOLT;
			case "inventory" -> STORAGE;
			case "trackers" -> TARGET;
			case "world" -> GLOBE;
			default -> INFO;
		};
	}
}
